"use client";

import { Download } from "lucide-react";
import { JOIN_QR_DISPLAY_URL, JOIN_QR_FILES } from "@/lib/joinQr";

// The free alternative to buying merch (docs/join-merch-store-plan.md): the
// same join QR code as a download, for partners who'd rather put it on their
// own menus, table tops or signs. Sits under the products on the Shop step.
//
// Plain same-origin <a download> links to static files generated by
// `npm run store:qr` (lib/joinQr.ts holds the URL). No network request is
// made by this component and nothing is recorded; the CDN serves ~5 KB.

const LINK_CLASS =
  "inline-flex min-h-[44px] items-center justify-center gap-1.5 rounded-xl px-4 py-2.5 text-sm font-black transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-300";

export const FreeQrDownload = () => (
  <section
    aria-labelledby="free-qr-heading"
    data-free-qr
    className="mt-4 rounded-2xl border border-slate-200 bg-white p-4 sm:flex sm:items-center sm:gap-5"
  >
    <img
      src={JOIN_QR_FILES.svg.src}
      width={112}
      height={112}
      alt={`QR code that opens ${JOIN_QR_DISPLAY_URL}`}
      loading="lazy"
      decoding="async"
      className="mx-auto h-28 w-28 shrink-0 sm:mx-0"
    />
    <div className="mt-3 min-w-0 sm:mt-0">
      <p className="text-xs font-bold uppercase tracking-wide text-emerald-700">Free</p>
      <h4 id="free-qr-heading" className="text-lg font-black leading-tight text-slate-900">
        Print your own QR code
      </h4>
      <p className="mt-1 text-sm leading-relaxed text-slate-600">
        Not ready for merch? Download our QR code for your menus, table tops or signs. It opens{" "}
        <span className="font-bold text-slate-900">{JOIN_QR_DISPLAY_URL}</span>, where guests at your venue can
        join and play.
      </p>
      <div className="mt-3 flex flex-wrap gap-2">
        <a
          href={JOIN_QR_FILES.png.src}
          download={JOIN_QR_FILES.png.download}
          className={`${LINK_CLASS} bg-indigo-600 text-white hover:bg-indigo-700`}
        >
          <Download aria-hidden="true" className="h-4 w-4" />
          Download PNG
        </a>
        <a
          href={JOIN_QR_FILES.svg.src}
          download={JOIN_QR_FILES.svg.download}
          className={`${LINK_CLASS} border border-slate-300 bg-white text-slate-900 hover:bg-slate-50`}
        >
          <Download aria-hidden="true" className="h-4 w-4" />
          SVG for printers
        </a>
      </div>
    </div>
  </section>
);
